import math


class Vector2D:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def length(self):
        return round(math.sqrt(self.x ** 2 + self.y ** 2), 2)

    def scaled(self, k):
        return (self.x * k, self.y * k)

